Method.Implementation:
	 #DIM status AS %Status
	 set status = $$$OK	 

	If $IsObject(..JavaGateway) {

	 try{
		 		$$$TRACE(" Calling MMIAddress: " _pRequest.RawContent) 				 				 	
		 		set pResponse=##class(Ens.StringResponse).%New()
		 		$$$TRACE("objCdrTuxService Object valid: "_$IsObject(..objCdrTuxService))

		 		if ($IsObject(..objCdrTuxService))
		 		{	
		 			$$$TRACE("Call addressUpdateMMI")	 		
		 			Set pResponse.StringValue = ..objCdrTuxService.addressUpdateMMI(pRequest.RawContent)
		 			Set respData = pResponse.StringValue	
		 			set respData = "1"	 		
		 			$$$TRACE(" Call after the Address Update .."_respData)		 				 		
		 		}
		 		else
		 		{
		 			Try {
		    			do ..OnTearDown()
	    			}catch{}
		 		}


	 }catch err{	
	 	set errText = $SYSTEM.Status.GetOneErrorText(status)
	    $$$LOGERROR("Exception in calling MmiAdd/Update: " _err.AsSystemError() _ " ErrData: " _ err.Data _ "; ErrCode:" _ err.Code _ ", " _ errText)
	    set status = $$$ERROR("Exception in calling MmiAdd/Update " _ err.Data _", " _  errText)		    	     	 		

	    if ((errText["CONNECTIONERROR")){
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }Elseif errText["RESEND"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }Elseif errText["DATAERROR"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName,errText)
	    }Elseif errText["SHUTDOWN"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }Else{
		    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }

	  if (errText'["DATAERROR"){
		    Try {
		    	do ..OnTearDown()
	    	}catch{}
            Set tSC = ..GetConnection(.tGateway, ..ConnectTimeout+10)
            $$$LOGINFO("Get new connection: " _ tSC)
			If $$$ISERR(tSC) {
				set errText = $SYSTEM.Status.GetOneErrorText(tSC)
				Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
			}Else {
				// Open the connection
				Do ..OnInit()
			}
	  }

  	  $$$LOGERROR("return status: " _ status) 
  	}	 


	}
	else
	{
		do ..OnTearDown()
		Do ..OnInit()
		set errText = "Connection to Java Gateway is not valid"
		Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	}
	return status


$$$TRACE(" $$$$$$$$$$$$$$$ Inside OnTearDown() method...")

Set tSC = $$$OK

Try {	 
	If $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		Set tSC = ..GetConnection(	..JavaGateway)
		If $$$ISOK(tSC) {				
			Do ..objCdrTuxService.shutdownTuxService()		
		}
		Set ..objCdrTuxService = $$$NULLOREF		
   }
}
Catch {
	Set tSC = $$$EnsSystemError
}
Set tSC = ##super()
Quit tSC
